interface Target {
  id: string; title: string; aliases: string[]; area: string; secondary?: string[]; tags: string[];
  statement: string; assumptions: string[]; motivation: string; resolution: string; gap: string;
  sources: (keyof typeof aiMlSources)[]; related?: string[]; framework?: boolean;
  efficiency?: string; dynamics?: boolean; checkedOn?: string;
}
const target = (p: Target): OpenProblem => ({
  schema_version: 1, id: `aiml-${p.id}`, domain: "ai_ml", kind: "open_question", title: p.title,
  aliases: p.aliases, primary_area: p.area, ...(p.secondary ? { secondary_areas: p.secondary } : {}),
  tags: [...p.tags, ...(p.efficiency ? ["architecture_efficiency"] : []), ...(p.dynamics ? ["dynamical_systems"] : [])],
  statement: p.statement, assumptions: p.assumptions,
  physics_motivation: p.efficiency ? `${p.motivation} Efficiency payoff: ${p.efficiency}` : p.motivation,
  resolution_target: p.resolution, formulation: p.framework ? "needs_framework" : "specified_model",
  status: "provisionally_open", review_level: "preliminary_source_check", compiled_on: p.checkedOn ?? checked,
  status_note: `${p.gap} ${p.sources.some(key => aiMlSources[key].role === "problem_statement") ? "This is an editorial reformulation of a published open problem." : "This is an editorial, source-motivated research target."} The preliminary review through ${p.checkedOn ?? checked} does not certify novelty or exclude an unlocated resolution.`,
  sources: p.sources.map(key => aiMlSources[key]),
  relations: (p.related ?? []).map(id => ({ id: `aiml-${id}`, type: "related", note: "Related learning or allocation mechanism; the models and resolution targets differ." })),
});
const efficientTarget = (p: Target & { efficiency: string }): OpenProblem => target({ ...p, checkedOn: "2026-11-20" });

