    aliases: ["Audit complexity for imperfect verifiers under adaptive policy optimization", "RLVR accepted-error control", "Adaptive reward hacking audit bounds"], area: "verification_and_search", secondary: ["learning_theory", "alignment"], tags: ["reward_hacking", "verifier_error", "active_auditing"],
